    /// <summary>Get what the system believes is the "current working directory."</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetCurrentDirectory</c>.</para>
    /// <para>
    /// For systems without a concept of a current working directory, this will still attempt to provide something
    /// reasonable.
    /// </para>
    /// <para>
    /// SDL does not provide a means to _change_ the current working directory; for platforms without this concept, this
    /// would cause surprises with file access outside of SDL.
    /// </para>
    /// <para>
    /// The returned path is guaranteed to end with a path separator ('\\' on Windows, '/' on most other platforms).
    /// </para>
    /// <para>Thread safety: It is safe to call this function from any thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <returns>
    /// a UTF-8 string of the current working directory in platform-dependent notation. NULL if there's a problem. This
    /// should be freed with SDL_free() when it is no longer needed.
    /// </returns>
    [LibraryImport("jade_native", EntryPoint = "SDL_GetCurrentDirectory")]
    [UnmanagedCallConv(CallConvs = [typeof(CallConvCdecl)])]
    public static partial byte* GetCurrentDirectory();
